<?php require __DIR__.'/../config.php'; admin_required(); $q=trim($_GET['q']??'');$status=$_GET['status']??'';$priority=$_GET['priority']??'';$where=[];$params=[];if($q){$where[]='(ticket_no LIKE ? OR name LIKE ? OR email LIKE ? OR subject LIKE ?)';array_push($params,"%$q%","%$q%","%$q%","%$q%");}if(in_array($status,['open','pending','resolved','closed'],true)){$where[]='status=?';$params[]=$status;}if(in_array($priority,['low','normal','high','urgent'],true)){$where[]='priority=?';$params[]=$priority;}$sql="SELECT * FROM tickets ".($where?'WHERE '.implode(' AND ',$where):'')." ORDER BY created_at DESC";$s=db()->prepare($sql);$s->execute($params);$tickets=$s->fetchAll();$stats=db()->query("SELECT COUNT(*) total,SUM(status='open') open_count,SUM(status='pending') pending_count,SUM(status='resolved') resolved_count FROM tickets")->fetch(); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin — SupportHub</title><link rel="stylesheet" href="../assets/style.css"></head><body class="dashboard"><nav><a class="brand" href="../index.php"><span class="logo">S</span> SupportHub</a><div class="navlinks"><a href="../index.php">View site</a><a href="logout.php">Sign out</a></div></nav><main class="dash"><div class="dashhead"><div><span class="eyebrow">ADMIN WORKSPACE</span><h1>Support requests</h1><p>Review, update and resolve customer conversations.</p></div><a class="primary btn" href="../submit.php">New request</a></div><div class="stats"><div><small>Total</small><strong><?=e((string)$stats['total'])?></strong></div><div><small>Open</small><strong><?=e((string)$stats['open_count'])?></strong></div><div><small>Pending</small><strong><?=e((string)$stats['pending_count'])?></strong></div><div><small>Resolved</small><strong><?=e((string)$stats['resolved_count'])?></strong></div></div><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Search tickets, names, emails..."><select name="status"><option value="">All statuses</option><?php foreach(['open','pending','resolved','closed'] as $x):?><option <?=$status===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><select name="priority"><option value="">All priorities</option><?php foreach(['low','normal','high','urgent'] as $x):?><option <?=$priority===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button>Filter</button></form><div class="tablewrap"><table><thead><tr><th>Ticket</th><th>Customer</th><th>Subject</th><th>Priority</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($tickets as $t):?><tr onclick="location.href='view.php?id=<?=$t['id']?>'"><td><b><?=e($t['ticket_no'])?></b></td><td><?=e($t['name'])?><small><?=e($t['email'])?></small></td><td><?=e($t['subject'])?></td><td><span class="priority <?=$t['priority']?>"><?=e(ucfirst($t['priority']))?></span></td><td><span class="badge <?=$t['status']?>"><?=e(ucfirst($t['status']))?></span></td><td><?=e(date('M j, Y',strtotime($t['created_at'])))?></td></tr><?php endforeach;?><?php if(!$tickets):?><tr><td colspan="6" class="center">No requests found.</td></tr><?php endif;?></tbody></table></div></main></body></html>